// The shape of the Sagax and Perspicax knowledge base (sagax_help).
// Generated by scripts/self-knowledge/generate.ts from the code, the
// catalogs and the docs; read by server/self-knowledge.ts. Types only.

export type KnowledgeKind =
  /** A short how-to whose every reference is checked by the generator test. */
  | "guide"
  /** A tool of the bots' catalog (agents MCP). */
  | "tool"
  /** A page or card of Settings, or an entry of a menu. */
  | "setting"
  | "menu"
  /** An engine (model CLI) the server can run. */
  | "engine"
  /** A section of a release's notes. */
  | "release"
  /** A section of the user docs or docs/. */
  | "doc"
  /** A section of AGENTS.md: the maintainers' notes, weighed below the docs. */
  | "notes"
  /** A group of the server's HTTP routes. */
  | "route"
  /** Perspicax: its console pages, settings, docs and release notes. */
  | "perspicax";

export interface KnowledgeSection {
  /** Stable id: `tool:<name>`, `setting:<section>`, `card:<cardId>`,
   * `doc:<path>#<slug>`, `release:<version>#<slug>`, `px:<...>`. */
  id: string;
  kind: KnowledgeKind;
  title: string;
  /** Where it is in the app, e.g. "Settings > Models and voice". */
  where?: string;
  /** Who may use it: a permission, admin only, member, solo. */
  access?: string;
  /** Extra search words (labels in French and English). */
  keywords?: string;
  text: string;
  /** The file it was read from. */
  source: string;
}

export interface KnowledgeBase {
  /** Sagax's version (package.json forkVersion). */
  version: string;
  /** Day the content last changed (UTC, YYYY-MM-DD). */
  generated: string;
  /** sha256 of the sections, so a rebuild with the same content keeps its day. */
  hash: string;
  perspicax?: { version: string; commit: string; date: string };
  counts: Record<string, number>;
  sections: KnowledgeSection[];
}

export interface PerspicaxSnapshot {
  version: string;
  commit: string;
  /** Commit day (UTC). */
  date: string;
  sections: KnowledgeSection[];
}
